import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 4

def design(feats):
    # Identify potential drivers by correlation with outcome
    drivers = []
    correlations = []

    # Calculate correlations for all features
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('clinical', 'cohort'):
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            correlations.append((abs(corr), fid))

    # Sort by absolute correlation strength and limit to MAX_DRIVERS
    correlations.sort(reverse=True)
    drivers = [fid for _, fid in correlations[:MAX_DRIVERS]]

    # If no strong drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select features with high mutual information and low correlation with drivers
    mi_scores = mutual_info_classif(feats.x, feats.y)
    selected_features = []

    # Filter out near-duplicates and correlated features
    feature_indices = {fid: i for i, fid in enumerate(feats.ids)}
    used_features = set()

    for i, fid in enumerate(feats.ids):
        if fid in used_features:
            continue

        # Check correlation with drivers
        is_correlated = False
        for driver_fid in drivers:
            if driver_fid in feature_indices:
                j = feature_indices[driver_fid]
                corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                if abs(corr) > 0.6:
                    is_correlated = True
                    break

        if not is_correlated:
            selected_features.append(fid)
            used_features.add(fid)

            # Add correlated features as products
            for other_fid in feats.ids:
                if other_fid == fid or other_fid in used_features:
                    continue
                j = feature_indices[other_fid]
                corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                if abs(corr) >= 0.6:
                    selected_features.append(other_fid)
                    used_features.add(other_fid)

    # Create products for highly correlated pairs
    products = []
    for i, fid_a in enumerate(selected_features):
        for j, fid_b in enumerate(selected_features[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, feature_indices[fid_a]], 
                              feats.x[:, feature_indices[fid_b]])[0, 1]) >= 0.6:
                products.append((fid_a, fid_b))

    # Weighted loading based on mutual information
    loadings = {}
    for fid in selected_features:
        idx = feature_indices[fid]
        loadings[fid] = mi_scores[idx]

    return Design(
        drivers=tuple(drivers),
        columns=tuple(selected_features),
        products=tuple(products),
        loadings=loadings
    )
